void osd_font_raw_85_load(void)
{
    uint16_t n = 4590, o = 0;
    uint8_t k, m;
    osd_tc_raw_begin(85);
    while (n != 0) {
        m = n > sizeof fbuf ? (uint8_t)sizeof fbuf : (uint8_t)n;
        for (k = 0; k < m; k++) fbuf[k] = font_raw_85[o + k];
        osd_tc_raw_put(fbuf, m);
        o += m;
        n -= m;
    }
    osd_tc_raw_end();
}
